// Command systool reports low-level OS information via native system calls.
package main

import (
	"fmt"
	"os"
	"runtime"

	"example.com/systool/internal/platform"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "systool:", err)
		os.Exit(1)
	}
}

func run() error {
	info, err := platform.GetInfo()
	if err != nil {
		return fmt.Errorf("get os info: %w", err)
	}
	uptime, err := platform.Uptime()
	if err != nil {
		return fmt.Errorf("get uptime: %w", err)
	}

	fmt.Printf("platform: %s/%s\n", runtime.GOOS, runtime.GOARCH)
	fmt.Printf("kernel:   %s %s\n", info.Name, info.Release)
	fmt.Printf("version:  %s\n", info.Version)
	fmt.Printf("uptime:   %s\n", uptime)

	if cols, rows, err := platform.TermSize(os.Stdout); err == nil {
		fmt.Printf("terminal: %dx%d\n", cols, rows)
	} else {
		fmt.Printf("terminal: n/a (%v)\n", err)
	}
	return nil
}
EOF
cat > internal/platform/platform.go <<'EOF'
// Package platform wraps OS-specific system calls behind a common API.
//
// Each supported OS has its own file selected by Go's filename and
// //go:build constraints:
//
//	platform_unix.go     linux, darwin (shared POSIX calls)
//	platform_linux.go    linux only
//	platform_darwin.go   darwin only
//	platform_windows.go  windows only
//	platform_other.go    fallback returning ErrUnsupported
//
// Use golang.org/x/sys/{unix,windows} rather than the frozen standard
// library syscall package.
package platform

import "errors"

// ErrUnsupported is returned on operating systems without an implementation.
var ErrUnsupported = errors.New("not supported on this platform")

// Info describes the running operating system kernel.
type Info struct {
	Name    string // e.g. "Linux", "Darwin", "Windows"
	Release string // kernel release / build number
	Version string // detailed version string
}
EOF
cat > internal/platform/platform_unix.go <<'EOF'
//go:build linux || darwin

package platform

import (
	"os"

	"golang.org/x/sys/unix"
)

// GetInfo returns kernel information via uname(2).
func GetInfo() (Info, error) {
	var u unix.Utsname
	if err := unix.Uname(&u); err != nil {
		return Info{}, err
	}
	return Info{
		Name:    unix.ByteSliceToString(u.Sysname[:]),
		Release: unix.ByteSliceToString(u.Release[:]),
		Version: unix.ByteSliceToString(u.Version[:]),
	}, nil
}

// TermSize returns the terminal dimensions of f via ioctl(TIOCGWINSZ).
func TermSize(f *os.File) (cols, rows int, err error) {
	ws, err := unix.IoctlGetWinsize(int(f.Fd()), unix.TIOCGWINSZ)
	if err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}
EOF
